--region init
function OverseaStoreOptionalGiftPopup:InitHandler()
    SetButtonAction(self.ClickClose, Bind(self, self.BtnCloseOnClickHandler))
    SetButtonAction(self.BtnClose, Bind(self, self.BtnCloseOnClickHandler))
end

function OverseaStoreOptionalGiftPopup:InitData()
    local parameters = checkTable(self.controller.Argument.parameters)
