--region handler
---关闭按钮点击回调
function OverseaStoreOptionalGiftPopup:BtnCloseOnClickHandler()
    self:RecordChoice(function()
        CfUtils.DialogClose(self.controller)
    end)
end

function OverseaStoreOptionalGiftPopup:OnGetItemByIndex(listView, index)
    local luaIndex = index + 1
    local cell = listView:NewListViewItem("OverseaMallDIYGiftRewardNode")
    local cellData = checkTable(self._data['rewardGroup' .. self._groupSelectedIdx][luaIndex])
    
    local goodsNode = cell.transform:Find('GoodNode')
    local isUnlock = self:IsItemUnlocked(cellData.goodsId)
    local lockNode = cell.transform:Find("StatusLock")
    CfUtils.SetActive(lockNode, not isUnlock)
    
    CfUtils.RefeshGoodGo2(goodsNode, cellData.goodsId, cellData.num, nil, nil, function()
        if not isUnlock then
            GameUtils.Toast(self:GetUnlockDesc(cellData.goodsId))
            return
        end
        self._choice[self._groupSelectedIdx] = luaIndex
        self:RefreshOptionalGoods()
        self:RefreshGoodsList()
        self:RefreshButton()
    end)
    local goodsScr = CfUtils.GetLuaScr(goodsNode, "Game.Behaviours.GoodNodeMB")
    if goodsScr then
        goodsScr:SetCheckState(luaIndex == checkInt(self._choice[self._groupSelectedIdx]))
    end
    return cell
end
--endregion handler

--region private
---刷新商品节点
function OverseaStoreOptionalGiftPopup:RefreshGoodsNode()
    local data = self._data
    CfUtils.RefeshGoodGo2(self.GoodNode, data.rewards[1].goodsId, data.rewards[1].num, nil ,nil, function()  end)

    -- 充值积分
    if isNotNull(data.payPoint) then
        CfUtils.SetActive(self.RechargePoints, true)
        CfUtils.FillText(self.PointTextDesc, string.format('x%d', checkInt(data.payPoint)))
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.CumulativeScore)
        CfUtils.FillImage(self.PointImgGoodsIcon, goodsVo.photoPath)
    else
        CfUtils.SetActive(self.RechargePoints, false)
    end 
end

---刷新可选商品
function OverseaStoreOptionalGiftPopup:RefreshOptionalGoods()
    local data = self._data
    --for i = 1, self.Layout.childCount do
    --    local go = self.Layout:GetChild(i - 1)
    --    CfUtils.SetActive(go, false)
    --end

    for i = 1, 3 do
        local rewardGroup = checkTable(data['rewardGroup' .. i])
        if next(rewardGroup) ~= nil then
            local go = nil
            if i > self.Layout.childCount then
                go = CfUtils.InstantiateGo(self.BtnRewardNode.gameObject, self.Layout)
            else
                go = self.Layout:GetChild(i - 1)
            end
            CfUtils.SetActive(go, true)

            local emptyNode = go.transform:Find('Root/Empty')
            local contentNode = go.transform:Find('Root/Content')
            local selectNode = go.transform:Find('Root/Select')
            local choiceId = checkInt(self._choice[i])
            CfUtils.SetActive(selectNode, i == checkInt(self._groupSelectedIdx))
            if choiceId == 0 then
                CfUtils.SetActive(emptyNode, true)
                CfUtils.SetActive(contentNode, false)
            else
                CfUtils.SetActive(emptyNode, false)
                CfUtils.SetActive(contentNode, true)
                local goodsNode = contentNode:Find('GoodNode')
                CfUtils.RefeshGoodGo2(goodsNode, rewardGroup[choiceId].goodsId, rewardGroup[choiceId].num)
            end

            SetButtonAction(go, function()
                self._groupSelectedIdx = i
                self:RefreshOptionalGoods()
                self:RefreshGoodsList()
                self:RefreshButton()
            end)
        end
    end

    local selectedNum = self:GetSelectedNum()
    local rewardsNum = self:GetRewardsNum()
    local format = "<color=#FF009C>%d</color>/%d"
    if selectedNum == rewardsNum then
        format = "%d/%d"
    end
    CfUtils.FillText(self.Number2TextDesc, string.format(format, selectedNum, rewardsNum))
end

---刷新道具列表
function OverseaStoreOptionalGiftPopup:RefreshGoodsList()
    local data = self._data
    local rewardGroup = checkTable(data['rewardGroup' .. self._groupSelectedIdx])
    if next(rewardGroup) == nil then
        return
    end

    if self.ListView.IsListViewInit then
        GameUtils.ReloadData(self.ListView, #rewardGroup)
    else
        self.ListView:InitGridView(#rewardGroup, Bind(self, self.OnGetItemByIndex))
    end

    local choiceId = checkInt(self._choice[self._groupSelectedIdx])
    if choiceId > 0 and rewardGroup[choiceId].goodsId then
        local goodsId = rewardGroup[choiceId].goodsId
        local num = rewardGroup[choiceId].num
        CfUtils.SetActive(self.RewardIndo, true)
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        CfUtils.FillText(self.TextDesc, goodsVo.desc)
        CfUtils.FillText(self.InfoTextDesc, goodsVo.name)
        local goodsType = GoodsUtils.GetIdType(goodsId)
        if goodsType == Constants.IDType.GoodsUsable then
            CfUtils.SetActive(self.BtnCheck, true)
            SetButtonAction(self.BtnCheck, function()
                GameUtils.ShowCommonGoodsTipsBoard(self.BtnCheck, goodsId, num)
            end)
        else
            CfUtils.SetActive(self.BtnCheck, false)
        end
    else
        CfUtils.SetActive(self.RewardIndo, false)
    end
end

---刷新按钮
function OverseaStoreOptionalGiftPopup:RefreshButton()
    local data = self._data
    local selectedNum = self:GetSelectedNum()
    local rewardsNum = self:GetRewardsNum()
    if selectedNum == rewardsNum then
        CfUtils.SetActive(self.BtnBuy, true)
        local isFree = OverseaStoreUtils.ProductIsFree(data)
        if isFree then
            CfUtils.SetActive(self.Free, true)
            CfUtils.SetActive(self.Paid, false)
        else
            CfUtils.SetActive(self.Free, false)
            CfUtils.SetActive(self.Paid, true)
            if isNotNull(data.payPoint) then
                local windowPricesId = CfUtils.GetWindowsPriceId(data)
                CfUtils.FillText(self.PaidTextDesc, CfUtils.GetCustomDisplayPrice(windowPricesId, data.channelProductId, 24))
                CfUtils.SetActive(self.PaidImgGoodsIcon, false)
            elseif next(checkTable(data.prices)) then 
                CfUtils.FillText(self.PaidTextDesc, data.prices[1].current)
                CfUtils.SetActive(self.PaidImgGoodsIcon, true)
                local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.prices[1].currency))
                CfUtils.FillImage(self.PaidImgGoodsIcon, currencyVo.photoPath)
            end
        end
        SetButtonAction(self.BtnBuy, function()
            self:RecordChoice(function()
                OverseaStoreMgr:OptionalGiftBuy(data, function()
                    CfUtils.DialogClose(self.controller)
                end)
            end)
        end)
    else
        CfUtils.SetActive(self.BtnBuy, false)
    end

    -- 库存
    if checkNumber(data.stock) == -1 then
        CfUtils.SetActive(self.Stock, false)
    else
        if selectedNum == rewardsNum then
            CfUtils.SetActive(self.Stock, true)
            CfUtils.FillText(self.StockTextDesc, data.currentStock)
        else
            CfUtils.SetActive(self.Stock, false)
        end
    end
end

---获取选中数量
function OverseaStoreOptionalGiftPopup:GetSelectedNum()
    local num = 0
    for i = 1, 3 do
        local choiceId = checkInt(self._choice[i])
        if choiceId > 0 then
            num = num + 1
        end
    end
    return num
end

---获取选中奖励数量
function OverseaStoreOptionalGiftPopup:GetRewardsNum()
    local num = 0
    for i = 1, 3 do
        local rewardGroup = checkTable(self._data['rewardGroup' .. i])
        if next(rewardGroup) ~= nil then
            num = num + 1
        end
    end
    return num
end

---记录选择
function OverseaStoreOptionalGiftPopup:RecordChoice(cb)
    if self:CheckIsChange() then
        local choiceId = table.concat(self._choice, ',')
        GameUtils.Request(Interfaces.StoreOptionalGiftChoice, {rewardsId = choiceId, productId = self._data.productId}, function()
            OverseaStoreMgr:SetOptionalGiftChoiceId(self._data.productId, choiceId)
            Events.Broadcast(Constants.EventNames.OVERSEA_STORE_REFRESH, OverseaStoreConstants.StoreType.OptionalGift)
            if cb then
                cb()
            end
        end)
    else
        if cb then
            cb()
        end
    end
end

---判断选中道具是否改变
function OverseaStoreOptionalGiftPopup:CheckIsChange()
    local isChange = false
    for i = 1, 3 do
        if self._choice[i] ~= self._originalChoice[i] then
            isChange = true
            break
        end
    end
    return isChange
end

---判断道具是否解锁
function OverseaStoreOptionalGiftPopup:IsItemUnlocked(goodsId)
    local conf = CfUtils.GetCfVo(AutoIds.IdSetting6415, 'OverseaStoreOptionalGiftUnlockVo', goodsId)
    if not conf then return true end

    return GameUtils.IsUnlocked(conf.unlockType, conf.unlockNum, conf.unlockId)
end

function OverseaStoreOptionalGiftPopup:GetUnlockDesc(goodsId)
    local conf = CfUtils.GetCfVo(AutoIds.IdSetting6415, 'OverseaStoreOptionalGiftUnlockVo', goodsId)
    if not conf then return '' end

    return GameUtils.GetUnlockDescr(conf.unlockType, conf.unlockNum, conf.unlockId)
end
--endregion private

return OverseaStoreOptionalGiftPopup